sparql_coverage.query:
PREFIX p: <https://hswm.invalid/kg-bundle-rdf/v1/prop/>
PREFIX r: <https://hswm.invalid/kg-bundle-rdf/v1/rel/>
SELECT ?gap ?criterion ?proposal ?source WHERE {
 ?g p:standard_graph_role "LEARNING_GAP"; p:name ?gap; r:HAS_CRITERION/p:acceptance ?criterion.
 ?p p:standard_graph_role "IMPLEMENTATION_PROPOSAL"; p:name ?proposal; r:ADDRESSES ?g; r:HAS_SOURCE/p:source_url ?source.
} ORDER BY ?gap ?proposal ?source
